import {motionPresetPlan,applyMotionPreset,motionPresets,presetNames} from '../animation/presets.js';
import {toSeconds,fromSeconds,formatTime} from '../animation/timing.js';
export function showMotionPresets(a){
 a.pause();a.properties.flush();a.stage.finishPath();const unit=a.timeline.measurement||'seconds',selected=a.timeline.selectedBlock?.(),blockIds=selected&&!selected.audio&&selected.b.kind==='animation'?{[selected.n.id]:selected.b.id}:{},start=a.time;
 const d=a.dialog('Motion presets',`<form><div class="dialog-grid"><label>Preset<select name="type">${motionPresets.map(type=>`<option value="${type}">${presetNames[type]}</option>`).join('')}</select></label><label>Duration (${unit})<input name="duration" type="number" min="${fromSeconds(a.doc,2/a.doc.fps,unit)}" step="any" value="${fromSeconds(a.doc,1,unit)}" required></label><label data-position-option>Direction<select name="direction"><option value="up">Up</option><option value="down">Down</option><option value="left">Left</option><option value="right">Right</option></select></label><label data-position-option>Distance (local pixels)<input name="distance" type="number" min="1" max="4096" step="1" value="100"></label><label data-ramp-option hidden>Speed ramp<select name="ramp"><option value="accelerate">Accelerate</option><option value="decelerate">Decelerate</option><option value="both">Accelerate then decelerate</option></select></label></div><p data-preset-preview role="status"></p><p data-preset-description class="subtle"></p><p class="subtle">Applies at the playhead to unlocked selected artwork. Only the preset’s position or opacity keys in this range are replaced; other parameters stay intact. Active/selected animation blocks constrain the range. Later saved keys remain. A hold guard keeps the preceding frame; on an already animated affected track, its incoming segment can change. One Apply is one undo step.</p><div class="dialog-actions"><button type="button" data-close>Cancel</button><button type="submit" class="primary" data-preset-apply>Apply preset</button></div></form>`,(form,dialog)=>{let result;a.mutate('Apply '+presetNames[form.get('type')],()=>{result=applyMotionPreset(a.doc,a.selected,start,{type:form.get('type'),duration:toSeconds(a.doc,Number(form.get('duration')),unit),direction:form.get('direction')||'up',distance:Number(form.get('distance')||100),ramp:form.get('ramp')||'accelerate',blockIds});a.keyIds=new Set(result.keyIds);});if(!result)return;dialog.close();a.render();a.toast(`${presetNames[result.type]} applied to ${result.entries.length} layer${result.entries.length===1?'':'s'}.`);});
 const options=()=>({type:d.querySelector('[name=type]').value,duration:toSeconds(a.doc,Number(d.querySelector('[name=duration]').value),unit),direction:d.querySelector('[name=direction]').value,distance:Number(d.querySelector('[name=distance]').value),ramp:d.querySelector('[name=ramp]').value,blockIds});
 function preview(){const choice=options(),position=['bounce','ramp'].includes(choice.type);d.querySelectorAll('[data-position-option]').forEach(el=>{el.hidden=!position;el.querySelectorAll('input,select').forEach(control=>control.disabled=!position);});d.querySelector('[data-ramp-option]').hidden=choice.type!=='ramp';d.querySelector('[name=ramp]').disabled=choice.type!=='ramp';d.querySelector('[name=duration]').min=fromSeconds(a.doc,(choice.type==='bounce'?7:choice.type==='fadeBoth'?4:2)/a.doc.fps,unit);d.querySelector('[data-preset-description]').textContent=choice.type==='bounce'?'Three decreasing rebounds return to the starting position. Motion uses local X/Y; transformed groups rotate these directions.':choice.type==='ramp'?'Two position keys change speed using the selected easing. Motion uses local X/Y, not a time-remapping effect.':choice.type==='fadeBoth'?'Fade from zero to the current opacity (or full opacity when currently zero), hold through the middle, then fade to zero.':choice.type==='fadeIn'?'Fade from zero to the current opacity, or full opacity when currently zero.':'Fade from the current opacity to zero.';
  try{const plan=motionPresetPlan(a.doc,a.selected,start,choice);d.querySelector('[data-preset-preview]').textContent=`${plan.entries.length} layer${plan.entries.length===1?'':'s'} · ${formatTime(a.doc,plan.start,unit)}–${formatTime(a.doc,plan.end,unit)} · ${plan.frames} frames · ${plan.collisions} existing parameter keys replaced${plan.skipped?' · '+plan.skipped+' locked/reference selections skipped':''}${plan.extendsTo>a.doc.duration?' · composition extends to '+formatTime(a.doc,plan.extendsTo,unit):''}. Final pose is on the last frame.${plan.incomingAdjustments?" Warning: incoming easing changes on "+plan.incomingAdjustments+" affected track(s).":""}`;d.querySelector('[data-preset-apply]').disabled=false;}catch(e){d.querySelector('[data-preset-preview]').textContent=e.message;d.querySelector('[data-preset-apply]').disabled=true;}}
 d.querySelectorAll('input,select').forEach(input=>input.addEventListener('input',preview));preview();return d;
}
